-- Neural semantic embeddings generated locally with sentence-transformers/paraphrase-multilingual-mpnet-base-v2.
-- Each vector embeds the concatenated question and answer; dimensions: 768.
-- If public.qa already exists with a different embedding dimension, migrate or recreate it before running this script.
create extension if not exists vector;

create table if not exists public.qa (
    id bigint generated by default as identity primary key,
    question text not null,
    answer text not null,
    embedding vector(768) not null
);


create or replace function public.match_qa(
    query_embedding vector(768),
    match_count integer default 1
)
returns table (
    id bigint,
    question text,
    answer text,
    similarity double precision
)
language sql
stable
security definer
set search_path = public, extensions
as $$
    select
        q.id,
        q.question,
        q.answer,
        1 - (q.embedding <=> query_embedding) as similarity
    from public.qa as q
    order by q.embedding <=> query_embedding
    limit least(greatest(match_count, 1), 10);
$$;

revoke all on function public.match_qa(vector, integer) from public;
grant execute on function public.match_qa(vector, integer) to anon, authenticated;


create index if not exists qa_embedding_hnsw_idx on public.qa using hnsw (embedding vector_cosine_ops);
